.lab-screen{font-family:"IBM Plex Sans Thai","Noto Sans Thai",Tahoma,sans-serif;color:#111827;font-size:14px}.lab-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:18px}.lab-metric{padding:15px 16px;border:1px solid #e5e7eb;border-radius:8px;background:#fff;color:#6b7280;font-size:12px}.lab-metric b{display:block;margin-top:4px;font-size:25px}.lab-metric small{font-size:12px;font-weight:400;color:#9ca3af}.blue{color:#2563eb}.red{color:#dc2626}.amber{color:#d97706}.green{color:#059669}.lab-toolbar{align-items:center;gap:10px;margin-bottom:16px}.lab-toolbar-filter{display:grid;grid-template-columns:minmax(280px,460px) 210px;justify-content:start}.lab-toolbar-received{display:grid;grid-template-columns:minmax(280px,460px) max-content;justify-content:start}.lab-toolbar-result{display:grid;grid-template-columns:minmax(280px,460px) 210px minmax(0,1fr) max-content}.lab-search-wrap{position:relative;width:100%;min-width:0}.lab-search-wrap:before{content:"⌕";position:absolute;z-index:2;left:12px;top:7px;color:#6b7280;font-size:20px;pointer-events:none}.lab-search{display:block!important;width:100%!important;height:40px!important;border:1px solid #d1d5db!important;border-radius:8px!important;background:#fff!important;color:#111827!important;padding:0 12px 0 36px!important;outline:none!important;box-sizing:border-box!important}.lab-select{display:block!important;width:210px!important;height:40px!important;border:1px solid #d1d5db!important;border-radius:8px!important;background:#fff!important;color:#111827!important;padding:0 12px!important;box-sizing:border-box!important;min-width:0!important}.lab-search:focus,.lab-select:focus{border-color:#93c5fd!important;box-shadow:0 0 0 3px #eff6ff}.lab-button{height:40px;padding:0 15px;border:1px solid #d1d5db;border-radius:8px;background:#fff;color:#374151;font-weight:600;cursor:pointer;white-space:nowrap}.lab-button:hover{background:#f9fafb}.lab-panel,.lab-queue{border:1px solid #e5e7eb;border-radius:8px;background:#fff;overflow:hidden}.lab-panel-head,.lab-queue-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:15px 16px;border-bottom:1px solid #e5e7eb}.lab-panel-head h2,.lab-queue-head h2{margin:0;font-size:16px}.lab-panel-head p,.lab-queue-head p,.lab-panel-head span,.lab-muted{margin:3px 0 0;color:#6b7280;font-size:12px}.lab-table-wrap{overflow-x:auto}.lab-table{width:100%;border-collapse:collapse;min-width:820px}.lab-table th{height:40px;padding:0 14px;text-align:left;background:#f9fafb;color:#6b7280;border-bottom:1px solid #e5e7eb;font-size:11px;font-weight:600}.lab-table td{padding:12px 14px;border-bottom:1px solid #e5e7eb}.lab-empty{padding:64px 20px;text-align:center;color:#6b7280;line-height:1.7}.lab-empty strong,.lab-detail-empty b{color:#374151}.lab-split{display:grid;grid-template-columns:360px minmax(0,1fr);gap:14px;min-height:590px}.lab-detail-empty{display:grid;place-items:center;border:1px dashed #d1d5db;border-radius:8px;background:#fff;color:#6b7280;text-align:center;line-height:1.8}.lab-flow{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:14px;padding:12px 14px;border-left:4px solid #2563eb;border-radius:4px;background:#eff6ff;color:#4b5563;font-size:12px}.lab-flow b{color:#1d4ed8;margin-right:4px}.lab-flow i{font-style:normal;color:#2563eb}.lab-spacer{min-width:0}@media(max-width:900px){.lab-metrics{grid-template-columns:1fr}.lab-toolbar-filter,.lab-toolbar-received,.lab-toolbar-result{display:grid;grid-template-columns:1fr;justify-content:stretch}.lab-select{width:100%!important}.lab-toolbar-result .lab-spacer{display:none}.lab-toolbar-result .lab-button{justify-self:start}.lab-split{grid-template-columns:1fr}.lab-queue{min-height:200px}.lab-detail-empty{min-height:240px}}
.bio-root{display:flex;flex-direction:column;gap:16px}.bio-specimen,.bio-summary{border:1px solid var(--el-border-color-lighter);border-radius:12px;padding:16px;background:var(--el-fill-color-blank)}.bio-specimen h3{margin:0 0 12px;font-size:15px}.bio-specimen-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:20px}.bio-sub{display:flex;flex-wrap:wrap;margin:10px 0 0 24px}.bio-specimen-fields{display:grid;gap:10px}.bio-toolbar{display:flex;align-items:center;gap:16px}.bio-toolbar>.el-input{max-width:520px}.bio-count{margin-left:auto;white-space:nowrap;text-align:right;color:var(--el-text-color-secondary)}.bio-count b,.bio-count strong,.bio-total strong{color:var(--el-color-primary)}.bio-groups{column-width:300px;column-gap:16px}.bio-group{break-inside:avoid;border:1px solid var(--el-border-color-lighter);border-radius:10px;overflow:hidden;margin:0 0 16px;background:#fff}.bio-group-title{display:flex;gap:8px;align-items:center;padding:11px 12px;background:var(--el-fill-color-light)}.bio-group-title b,.bio-name{flex:1}.bio-group-title span{font-size:11px;color:var(--el-text-color-secondary)}.bio-item{display:flex;align-items:center;gap:8px;padding:7px 12px;border-top:1px solid var(--el-border-color-lighter);font-size:13px}.bio-code{min-width:48px;color:var(--el-color-primary);font-weight:700}.bio-price{min-width:72px;text-align:right;color:var(--el-text-color-secondary);font-variant-numeric:tabular-nums}.bio-minute{width:92px}.bio-summary-head,.bio-total{display:flex;justify-content:space-between;align-items:center}.bio-none{padding:12px 0;color:var(--el-text-color-placeholder)}.bio-selected{display:flex;align-items:center;gap:8px;padding:7px 0;border-top:1px solid var(--el-border-color-lighter)}.bio-selected>span:nth-child(2){flex:1}.bio-selected small{color:var(--el-text-color-secondary)}.bio-total{padding-top:12px;font-size:15px}.bio-send{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 16px;border:1px solid var(--el-color-primary-light-7);border-radius:12px;background:var(--el-color-primary-light-9)}.bio-send b{display:block;color:var(--el-text-color-primary)}.bio-send span{display:block;margin-top:3px;font-size:12px;color:var(--el-text-color-secondary)}@media(max-width:700px){.bio-specimen-grid{grid-template-columns:1fr}.bio-toolbar{align-items:stretch;flex-direction:column}.bio-toolbar>.el-input{max-width:none}.bio-count{margin-left:0;text-align:left}.bio-groups{column-width:auto}.bio-sub{margin-left:0}.bio-send{align-items:stretch;flex-direction:column}}
